import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getUserRole } from '../../Utils/AuthUtils';

export default function PostLoginLanding() {
    const navigate = useNavigate();
    const userRole = getUserRole();
    
    // Redirect to appropriate dashboard if user role is not recognized
    if (!userRole) {
        navigate('/studio');
    }

    const getDashboardLink = () => {
        if (userRole === 'seller') {
            return '/studio/seller';
        } else if (userRole === 'influencer') {
            return '/studio/influencer';
        }
        return '/studio/dashboard';
    };

    const getRoleSpecificOptions = () => {
        if (userRole === 'seller') {
            return [
                { 
                    title: 'My Products', 
                    description: 'Manage your product catalog and inventory', 
                    icon: 'ri-shopping-bag-line',
                    link: '/studio/seller/products'
                },
                { 
                    title: 'My Reels', 
                    description: 'View and manage your uploaded reels', 
                    icon: 'ri-movie-line',
                    link: '/studio/seller/reels'
                },
                { 
                    title: 'Upload Reel', 
                    description: 'Create and upload new reels for your products', 
                    icon: 'ri-upload-cloud-line',
                    link: '/studio/seller/upload'
                }
            ];
        } else if (userRole === 'influencer') {
            return [
                { 
                    title: 'My Campaigns', 
                    description: 'View and manage your active campaigns', 
                    icon: 'ri-megaphone-line',
                    link: '/studio/influencer/campaigns'
                },
                { 
                    title: 'My Reels', 
                    description: 'View and manage your uploaded reels', 
                    icon: 'ri-movie-line',
                    link: '/studio/influencer/reels'
                },
                { 
                    title: 'Upload Reel', 
                    description: 'Create and upload new reels for campaigns', 
                    icon: 'ri-upload-cloud-line',
                    link: '/studio/influencer/upload'
                }
            ];
        }
        return [];
    };

    const generalOptions = [
        { 
            title: 'Profile', 
            description: 'Update your profile information and settings', 
            icon: 'ri-user-line',
            link: '/studio/profile'
        },
        { 
            title: 'Settings', 
            description: 'Configure your account preferences', 
            icon: 'ri-settings-line',
            link: '/studio/settings'
        },
        { 
            title: 'All Reels', 
            description: 'Browse all available reels', 
            icon: 'ri-play-list-line',
            link: '/studio/reels'
        }
    ];

    const allOptions = [...getRoleSpecificOptions(), ...generalOptions];

    return (
        <div className="container-fluid">
            <div className="row">
                <div className="col-12">
                    <div className="page-title-box d-sm-flex align-items-center justify-content-between">
                        <h4 className="mb-sm-0">Dashboard</h4>
                        <div className="page-title-right">
                            <ol className="breadcrumb m-0">
                                <li className="breadcrumb-item">Studio</li>
                                <li className="breadcrumb-item active">Dashboard</li>
                            </ol>
                        </div>
                    </div>
                </div>
            </div>

            <div className="row">
                <div className="col-xl-12">
                    <div className="card">
                        <div className="card-header">
                            <h4 className="card-title mb-0">Welcome to Studio Platform</h4>
                        </div>
                        <div className="card-body">
                            <p className="text-muted">
                                Choose from the options below to get started with your {userRole} dashboard.
                            </p>
                            
                            <div className="row mt-4">
                                {allOptions.map((option, index) => (
                                    <div className="col-md-6 col-lg-4" key={index}>
                                        <Link to={option.link} className="card border shadow-none mb-4">
                                            <div className="card-body">
                                                <div className="d-flex align-items-center">
                                                    <div className="flex-shrink-0 me-3">
                                                        <div className="avatar-sm">
                                                            <span className="avatar-title bg-light rounded-circle">
                                                                <i className={`${option.icon} text-primary`}></i>
                                                            </span>
                                                        </div>
                                                    </div>
                                                    <div className="flex-grow-1">
                                                        <h5 className="fs-15 mb-1">{option.title}</h5>
                                                        <p className="text-muted mb-0">{option.description}</p>
                                                    </div>
                                                    <div className="flex-shrink-0">
                                                        <i className="ri-arrow-right-s-line fs-18 text-muted"></i>
                                                    </div>
                                                </div>
                                            </div>
                                        </Link>
                                    </div>
                                ))}
                            </div>
                            
                            <div className="mt-4 text-center">
                                <Link to={getDashboardLink()} className="btn btn-primary">
                                    Go to Main Dashboard
                                </Link>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
